INSERT INTO `ai_playerbot_texts` (`name`, `text`, `say_type`, `reply_type`, `text_loc1`, `text_loc2`, `text_loc3`, `text_loc4`, `text_loc5`, `text_loc6`, `text_loc7`, `text_loc8`) VALUES
('string_no_travel',             'No where to travel. Idling a bit.',            0, 0, '', 'Nulle part où voyager. Je traîne un peu.', 'Nirgendwo hinzureisen. Ich stehe rum.', '无处旅行，闲逛一会儿。', '', 'Sin destino. Descansando un poco.', '', 'Некуда идти. Бездельничаю.'),
('string_reposition_los',        'Repositioning to exit the LoS target!',        0, 0, '', 'Repositionnement pour sortir du LoS!', 'Neupositionierung um LoS zu verlassen!', '重新定位以退出视线目标！', '', '¡Reposicionando para salir del LoS!', '', 'Перепозиционируюсь для выхода из зоны ЛОС!'),
('string_thanks_invite',         'Thanks for the invite!',                        0, 0, '', 'Merci pour l\'invitation!', 'Danke für die Einladung!', '谢谢邀请！', '', '¡Gracias por la invitación!', '', 'Спасибо за приглашение!'),
('string_not_in_guild',          'I\'m not in your guild!',                       0, 0, '', 'Je ne suis pas dans ta guilde!', 'Ich bin nicht in deiner Gilde!', '我不在你的公会！', '', '¡No estoy en tu hermandad!', '', 'Я не в твоей гильдии!'),
('string_no_guild_bank',         'Cannot find the guild bank nearby',             0, 0, '', 'Impossible de trouver la banque de guilde.', 'Gildenbank nicht in der Nähe gefunden.', '附近找不到公会银行。', '', 'No se encontró el banco de hermandad.', '', 'Банк гильдии не найден поблизости'),
('string_cant_unlock_item',      'I can\'t unlock this item.',                    0, 0, '', 'Je ne peux pas déverrouiller cet objet.', 'Ich kann diesen Gegenstand nicht entsperren.', '我无法解锁这个物品。', '', 'No puedo desbloquear este objeto.', '', 'Не могу разблокировать этот предмет.'),
('string_ignored_spells_empty',  'Ignored spell list is empty',                   0, 0, '', 'La liste des sorts ignorés est vide.', 'Liste der ignorierten Zauber ist leer.', '忽略法术列表为空。', '', 'La lista de hechizos ignorados está vacía.', '', 'Список игнорируемых заклинаний пуст'),
('string_no_glyphs',             'No glyphs equipped',                            0, 0, '', 'Aucun glyphe équipé.', 'Keine Glyphen ausgerüstet.', '没有装备雕文。', '', 'Sin glifos equipados.', '', 'Глифы не установлены'),
('string_pet_autocast_toggled',  'Pet autocast spells have been toggled.',        0, 0, '', 'Les sorts automatiques du familier ont été basculés.', 'Haustier-Automatikzauber wurden umgeschaltet.', '宠物自动施法已切换。', '', 'Los hechizos automáticos de la mascota fueron alternados.', '', 'Автоматические заклинания питомца переключены.'),
('string_disable_disperse',      'Disable disperse',                              0, 0, '', 'Désactiver la dispersion.', 'Verteilen deaktivieren.', '禁用分散。', '', 'Desactivar dispersión.', '', 'Отключаю рассеивание');
